cat > src/claimOffice.ts <<'EOF'
export interface Item {
  type: string;
}

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};

const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

export function basePremium(items: Item[]): number {
  const runes = items.filter((item) => item.type === 'rune');
  if (runes.length === BLOCK_SIZE) {
    return BLOCK_PREMIUM;
  }
  return items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
}
EOF
pnpm test 2>&1 | grep -E "AssertionError|Tests "

