export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const COMPONENTS = ['rune', 'moonstone'];
const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;
const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;
const CURSE_SURCHARGE = 0.5;
const LOYALTY_YEARS = 2;
const LOYALTY_DISCOUNT = 0.2;
const FOLLOW_UP_DISCOUNT = 0.15;
const HIGH_ENCHANTMENT = 5;
const HIGH_ENCHANTMENT_SURCHARGE = 0.3;

function groupPremium(type: string, count: number): number {
  if (COMPONENTS.includes(type) && count === BLOCK_SIZE) {
    return BLOCK_PREMIUM;
  }
  return count * BASE_PREMIUMS[type];
}

export function basePremium(items: Item[]): number {
  const counts = new Map<string, number>();
  items.forEach((item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1));
  return [...counts].reduce((sum, [type, count]) => sum + groupPremium(type, count), 0);
}

export interface QuoteStep {
  op: 'quote';
  items: Item[];
}

export interface Customer {
  yearsWithMHPCO: number;
}

export interface Scenario {
  customer: Customer;
  steps: QuoteStep[];
}

export interface QuoteResult {
  premium: number;
}

function surchargeRate(item: Item): number {
  let rate = 0;
  if (item.cursed) {
    rate += CURSE_SURCHARGE;
  }
  if ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT) {
    rate += HIGH_ENCHANTMENT_SURCHARGE;
  }
  return rate;
}

function policyRate(customer: Customer, isFollowUp: boolean): number {
  let rate = FIRST_INSURANCE_SURCHARGE;
  if (isFollowUp) {
    rate -= FOLLOW_UP_DISCOUNT;
  }
  if (customer.yearsWithMHPCO >= LOYALTY_YEARS) {
    rate -= LOYALTY_DISCOUNT;
  }
  return rate;
}

function quotePremium(items: Item[], customer: Customer, isFollowUp: boolean): number {
  const base = basePremium(items);
  const itemSurcharges = items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type] * surchargeRate(item), 0);
  return Math.ceil(base + itemSurcharges + base * policyRate(customer, isFollowUp) + PROCESSING_FEE);
}

export function runScenario(scenario: Scenario): { results: QuoteResult[] } {
  return { results: scenario.steps.map((step, index) => ({ premium: quotePremium(step.items, scenario.customer, index > 0) })) };
}

